// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(bool isPausedManipulated) public {
        vm.assume(isPausedManipulated == false);
        bool pausedResult = c.paused();
        bool fnReverted;
        try c.depositUsdc(1, address(0x1)) {
            fnReverted = false;
        } catch {
            fnReverted = true;
        }
        assertTrue(pausedResult != fnReverted);
    }
}
